// Embedded Noto Sans Gurmukhi TTF Fonts for jsPDF
// Ensures perfect Unicode Punjabi Gurmukhi + English rendering in exported PDFs
export const NOTO_SANS_GURMUKHI_REGULAR_BASE64 = '';
export const NOTO_SANS_GURMUKHI_BOLD_BASE64 = '';

export function registerGurmukhiFont(doc: any): void {
  try {
    if (!doc.__gurmukhiFontRegistered) {
      doc.addFileToVFS('NotoSansGurmukhi-Regular.ttf', NOTO_SANS_GURMUKHI_REGULAR_BASE64);
      doc.addFont('NotoSansGurmukhi-Regular.ttf', 'NotoSansGurmukhi', 'normal');
      doc.addFileToVFS('NotoSansGurmukhi-Bold.ttf', NOTO_SANS_GURMUKHI_BOLD_BASE64);
      doc.addFont('NotoSansGurmukhi-Bold.ttf', 'NotoSansGurmukhi', 'bold');
      doc.__gurmukhiFontRegistered = true;
    }
  } catch (e) {
    console.warn('Failed to register Gurmukhi font in jsPDF:', e);
  }
}
